from abc import abstractmethod

from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.trace_post_processor import TracePostProcessor


class CustomTraceBase(object):

    @abstractmethod
    def custom_tracers(self, custom_profile, trace_type, **kwargs):
        pass

    @abstractmethod
    def get_l2_5g(self, included_trace_mode, **kwargs):
        pass

    def _generate_custom_trace_profile(self, requirements, trace_type, **kwargs):
        tracers = []
        l2_traces = []
        for requirement in requirements:
            if trace_type == trace_type and requirement.startswith('L2'):
                l2_traces.append(requirement)
            else:
                tracers += self.custom_tracers(custom_profile=requirement,
                                               trace_type=trace_type,
                                               **kwargs)
        if l2_traces:
            tracers += self.get_l2_5g(included_trace_mode=l2_traces, kwargs=kwargs)
        return tracers

    @staticmethod
    def custom_control_plane_interface(control_plane_interface, monitoring_profiles,
                                       drb_monitoring_profiles=None, drb_monitoring_tail_cutter=None):
        params = []
        if monitoring_profiles is not None:
            params.append({
                "name": "monitoringProfiles",
                "values": monitoring_profiles.split(",")
            })
        if control_plane_interface is not None:
            params.append({
                "name": "commonControlPlaneInterface",
                "values": [
                    str(control_plane_interface)
                ]
            })
        if drb_monitoring_profiles is not None:
            params.append({
                "name": "drbProfiles",
                "values": drb_monitoring_profiles.split(",")
            }
            )
            if drb_monitoring_tail_cutter is not None:
                params.append({
                    "name": "tailCutter",
                    "values": [
                        str(drb_monitoring_tail_cutter)
                    ]
                })
        return params

    @staticmethod
    def custom_l1_stream(l1_trace, outputmode):
        params = [
            {
                "name": "traceIds",
                "values": l1_trace
            },
            {
                "name": "subTypes",
                "values": ['0' for _ in range(0, len(l1_trace))]
            },
            {
                "name": "nbReports",
                "values": ['0' for _ in range(0, len(l1_trace))]
            },
            {
                "name": "dscp",
                "values": [
                    "0"
                ]
            },
            {
                "name": "outputMode",
                "values": [
                    outputmode
                ]
            }]
        return params

    @staticmethod
    def create_emil_decoder_post_processing(emil_profile_values):
        return TracePostProcessor(
            id="emil-decoder",
            params=[
                {
                    "name": "emil-profile",
                    "values": [
                        emil_profile_values
                    ]
                }])

    @staticmethod
    def custom_syslog_vran(kwargs):
        dscp = kwargs.get('dscp', "0")
        syslog_format = kwargs.get('syslog_format', "RFC5424")
        protocol = kwargs.get('protocol', "UDP")
        max_file_size_in_kb = kwargs.get('max_file_size_in_kb', "51200")
        max_file_time_in_sec = kwargs.get('max_file_time_in_sec', "18000")
        params = [
            {
                "name": "dscp",
                "values": [
                    dscp
                ]
            },
            {
                "name": "format",
                "values": [
                    syslog_format
                ]
            },
            {
                "name": "protocol",
                "values": [
                    protocol
                ]
            },
            {
                "name": "fileSizeKB",
                "values": [
                    max_file_size_in_kb
                ]
            },
            {
                "name": "fileTimeSec",
                "values": [
                    max_file_time_in_sec
                ]
            }
        ]
        return params

    @staticmethod
    def custom_l1iq_vdu(l1iq_direction):
        params = [
            {
                "name": "sfn",
                "values": [
                    "65535"
                ]
            },
            {
                "name": "slot",
                "values": [
                    "0"
                ]
            },
            {
                "name": "captureOnEvent",
                "values": [
                    "false"
                ]
            },
            {
                "name": "capturePeriod",
                "values": [
                    "1000"
                ]
            },
            {
                "name": "collectionCount",
                "values": [
                    "0"
                ]
            },
            {
                "name": "eitherDLorUL",
                "values": [
                    l1iq_direction
                ]
            }]
        return params
